// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    Log logContract;

    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= 1 ether);

        logContract = new Log();
        c.SetLogFile(address(logContract));
        c.SetMinSum(1);
        c.Initialized();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        uint256 historyLength = logContract.HistoryLength();
        assertTrue(historyLength >= 1);
    }
}

contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val, string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }

    function HistoryLength() public view returns (uint256) {
        return History.length;
    }
}
